SELECT
log.*,
mdl.tool_name,
mdl.tool_description,
mdl.tool_platform,
mdl.action_type,
mdl.run_table,
mdl.control_type
FROM
mp_devops_load_scene_result_log log
inner join
mp_devops_load mdl
on log.id = mdl.id


        and mdl.pk = #{param.pk}


        and mdl.pk in

            #{item}



        and log.scene_id = #{param.sceneId}


        and log.create_time >= #{param.beginTime, jdbcType=TIMESTAMP}


        and log.create_time <= #{param.overTime, jdbcType=TIMESTAMP}



    limit #{param.offset}, #{param.pageSize}

SELECT
count(0)
FROM
mp_devops_load_scene_result_log log
inner join
